<?php

declare(strict_types=1);

namespace App\Policies;

use Illuminate\Foundation\Auth\User as AuthUser;

/**
 * Generated by Shield. SEO for single pages; site-wide SEO is gated by the
 * manage_seo permission on its own page.
 */
final class SeoPagePolicy
{
    public function viewAny(AuthUser $actor): bool
    {
        return $actor->can('view_any:seo_page');
    }

    public function view(AuthUser $actor): bool
    {
        return $actor->can('view:seo_page');
    }

    public function create(AuthUser $actor): bool
    {
        return $actor->can('create:seo_page');
    }

    public function update(AuthUser $actor): bool
    {
        return $actor->can('update:seo_page');
    }

    public function delete(AuthUser $actor): bool
    {
        return $actor->can('delete:seo_page');
    }

    public function deleteAny(AuthUser $actor): bool
    {
        return $actor->can('delete_any:seo_page');
    }
}
